extension Fuzz {
extension VersionTuple: Comparable {
  public static func < (lhs: VersionTuple, rhs: VersionTuple) -> Bool
{
    return lhs.normalized.components.lexicographicallyPrecedes( /* c */ .normalized.components)
  }
}
}

